using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class ParkingShaderRepairVerify{static ParkingShaderRepairVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("ParkingShaderRepairVerify.request"))return;File.Delete("ParkingShaderRepairVerify.request");try{var names=new[]{"Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Parking Cafe.mat","Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Parking Building.mat","Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Markings.mat","Assets/Scenes/Oasis/RoadAtlas/Road Atlas.mat"};var lines=names.Select(path=>{var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m)throw new Exception("Missing "+path);var errors=ShaderUtil.GetShaderMessages(m.shader).Where(v=>v.severity.ToString()=="Error").ToArray();if(errors.Length>0)throw new Exception(m.name+": "+string.Join(" | ",errors.Select(v=>v.message)));return m.name+": shader errors=0";}).ToArray();File.WriteAllLines("FinalEnvironmentRoadReview/ParkingShaderRepairVerify.txt",lines);}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/ParkingShaderRepairVerify.txt",e.ToString());Debug.LogException(e);}}}
